  { id:1,  name:"Amira Benali",   email:"amira@ifa.edu.dz",    university:"IFA",   level:"L3", wilaya:"Alger",    skills:["React","Node.js"],    status:"pending",   company:"Sonatrach Digital", role:"Full-Stack Developer" },
  { id:2,  name:"Sara Maamri",    email:"sara@ifa.edu.dz",     university:"IFA",   level:"M1", wilaya:"Alger",    skills:["Python","SQL"],        status:"pending",   company:"Ooredoo Labs",       role:"Data Analyst" },
  { id:3,  name:"Lina Zouaoui",   email:"lina@umbb.dz",        university:"UMBB",  level:"L3", wilaya:"Boumerdès",skills:["React","TypeScript"],  status:"placed",    company:"Djezzy Tech",        role:"Backend Engineer" },
  { id:4,  name:"Karim Hadj",     email:"karim@usthb.dz",      university:"USTHB", level:"M1", wilaya:"Alger",    skills:["Flutter","Firebase"],  status:"placed",    company:"Mobilis IT",         role:"Mobile Developer" },
  { id:5,  name:"Yacine Bouzid",  email:"yacine@esi.dz",       university:"ESI",   level:"L3", wilaya:"Alger",    skills:["Python","R"],          status:"searching", company:null, role:null },
  { id:6,  name:"Amine Ferhat",   email:"amine@usthb.dz",      university:"USTHB", level:"M2", wilaya:"Alger",    skills:["Docker","Linux"],      status:"pending",   company:"Cevital Digital",    role:"DevOps Intern" },
  { id:7,  name:"Rania Oussaid",  email:"rania@ifa.edu.dz",    university:"IFA",   level:"L3", wilaya:"Blida",    skills:["React","MongoDB"],     status:"searching", company:null, role:null },
  { id:8,  name:"Hamza Taleb",    email:"hamza@umbb.dz",        university:"UMBB",  level:"M1", wilaya:"Boumerdès",skills:["Java","Spring Boot"],  status:"placed",    company:"BNA Digital",        role:"Backend Intern" },
  { id:9,  name:"Nour Brahimi",   email:"nour@usthb.dz",       university:"USTHB", level:"L3", wilaya:"Alger",    skills:["C++","Embedded"],      status:"searching", company:null, role:null },
  { id:10, name:"Cylia Mebarki",  email:"cylia@ifa.edu.dz",    university:"IFA",   level:"M2", wilaya:"Alger",    skills:["TensorFlow","Python"], status:"placed",    company:"CERIST",             role:"AI/ML Intern" },
];

const STATUS_CFG = {
  placed:    { badge:"badge-green",  label:"Placed",    dot:"bg-blush"  },
  searching: { badge:"badge-orange", label:"Searching", dot:"bg-cream"  },
  pending:   { badge:"badge-blue",   label:"Pending",   dot:"bg-soft"   },
};

export default function AdminStudents() {
  const [search, setSearch]   = useState("");
  const [wilaya, setWilaya]   = useState("All");
  const [level,  setLevel]    = useState("All");
  const [status, setStatus]   = useState("All");
  const [selected, setSelected] = useState(null);

  const filtered = STUDENTS.filter(s => {
    const q = search.toLowerCase();
    const matchQ = !q || s.email.toLowerCase().includes(q) || s.skills.some(sk => sk.toLowerCase().includes(q));
    const matchW = wilaya === "All" || s.wilaya === wilaya;
    const matchL = level  === "All" || s.level  === level;
    const matchS = status === "All" || STATUS_CFG[s.status].label === status;
    return matchQ && matchW && matchL && matchS;
  });

  const placed    = STUDENTS.filter(s => s.status === "placed").length;
  const searching = STUDENTS.filter(s => s.status === "searching").length;
  const pending   = STUDENTS.filter(s => s.status === "pending").length;

  return (
    <AdminLayout active="students">
      <div className="p-5 md:p-8"></div>
      {/* Header */}
        <div className="anim-fade-up mb-6">
          <p className="text-xs font-semibold text-[#2E7DF7] uppercase tracking-widest mb-1">Students</p>
          <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl tracking-tight">Student placements</h1>
          <p className="text-slate-400 text-sm font-light mt-0.5">{STUDENTS.length} registered · {placed} placed · {searching} searching</p>
        </div>

        {/* Mini stats */}
        <div className="anim-fade-up anim-d1 grid grid-cols-3 gap-3 mb-5">
          {[
            { label:"Placed",    value:placed,    color:"bg-blush border-blush"  },
            { label:"Searching", value:searching, color:"bg-cream border-cream"  },
            { label:"Pending",   value:pending,   color:"bg-soft border-soft"    },
          ].map(({ label, value, color }) => (
            <div key={label} className={`card border p-3 text-center ${color}`}>
              <div className="font-syne font-extrabold text-2xl text-slate-900">{value}</div>
              <div className="text-xs font-semibold text-slate-500 mt-0.5">{label}</div>
            </div>
          ))}
        </div>

        {/* Filters */}
        <div className="anim-fade-up anim-d2 card border border-slate-200 p-4 mb-5">
          <div className="flex flex-col md:flex-row gap-3">
            <div className="relative flex-1">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm">🔍</span>
              <input type="text" placeholder="Search by name, email or skill…" value={search}
                onChange={e => setSearch(e.target.value)} className="input-field pl-9" />
            </div>
            <select value={wilaya} onChange={e => setWilaya(e.target.value)} className="input-field md:w-36">
              {WILAYAS.map(w => <option key={w}>{w}</option>)}
            </select>
            <select value={level} onChange={e => setLevel(e.target.value)} className="input-field md:w-28">
              {LEVELS.map(l => <option key={l}>{l}</option>)}
            </select>
            <select value={status} onChange={e => setStatus(e.target.value)} className="input-field md:w-32">
              {STATUSES.map(s => <option key={s}>{s}</option>)}
            </select>
          </div>
        </div>

        <div className="grid md:grid-cols-5 gap-5">

          {/* Student list */}
          <div className="md:col-span-3 anim-fade-up anim-d3 space-y-2">
            {filtered.length > 0 ? filtered.map(s => {
              const sc = STATUS_CFG[s.status];
              return (
                <div key={s.id} onClick={() => setSelected(s)}
                  className={`card border cursor-pointer transition-all p-4 ${
                    selected?.id === s.id ? "border-[#2E7DF7] bg-soft/30" : "border-slate-200 hover:border-soft"
                  }`}>
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-soft flex items-center justify-center text-sm font-bold text-slate-800 font-syne shrink-0">
                      {s.name.split(" ").map(n=>n[0]).join("")}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="font-semibold text-sm text-slate-800">{s.name}</div>
                      <div className="text-xs text-slate-400">{s.level} · {s.university} · {s.wilaya}</div>
                    </div>
                    <span className={`badge ${sc.badge} shrink-0`}>{sc.label}</span>
                  </div>
                  <div className="flex flex-wrap gap-1.5 mt-2.5">
                    {s.skills.map(sk => <span key={sk} className="skill-chip">{sk}</span>)}
                  </div>
                  {s.company && (
                    <div className="mt-2 text-xs text-slate-500">🏢 {s.company} · {s.role}</div>
                    )}
                </div>
              );
            }) : (
              <div className="text-center py-14">
                <div className="text-4xl mb-2">🔍</div>
                <p className="text-sm text-slate-400">No students match your filters.</p>
              </div>
            )}
          </div>

          {/* Student detail */}
          <div className="md:col-span-2 anim-fade-up anim-d3">
            {selected ? (() => {
              const sc = STATUS_CFG[selected.status];
              return (
                <div className="card border border-slate-200 p-5 sticky top-4">
                  <div className="flex items-start gap-4 mb-5 pb-5 border-b border-slate-100">
                    <div className="w-14 h-14 rounded-2xl bg-soft flex items-center justify-center text-xl font-bold text-slate-900 font-syne shrink-0">
                      {selected.name.split(" ").map(n=>n[0]).join("")}
                    </div>
                    <div className="flex-1">
                      <h2 className="font-syne font-extrabold text-slate-900 text-lg">{selected.name}</h2>
                      <p className="text-slate-500 text-sm">{selected.level} · {selected.university}</p>
                      <div className="flex flex-wrap gap-2 mt-1.5">
                        <span className={`badge ${sc.badge}`}>{sc.label}</span>
                        <span className="badge badge-slate">📍 {selected.wilaya}</span>
                      </div>
                    </div>
                  </div>

                  <div className="space-y-3 mb-5">
                    {[
                      { k:"Email",      v:selected.email },
                      { k:"University", v:selected.university },
                      { k:"Level",      v:selected.level },
                      { k:"Wilaya",     v:selected.wilaya },
                    ].map(({ k, v }) => (
                      <div key={k} className="flex justify-between text-sm">
                        <span className="text-slate-400">{k}</span>
                        <span className="font-medium text-slate-700">{v}</span>
                      </div>
                    ))}
                  </div>

                  <div className="mb-5">
                    <h4 className="text-xs font-semibold text-slate-400 uppercase tracking-widest mb-2">Skills</h4>
                    <div className="flex flex-wrap gap-1.5">
                      {selected.skills.map(sk => <span key={sk} className="skill-chip">{sk}</span>)}
                    </div>
                  </div>

                  {/* Placement info */}
                  <div className={`rounded-xl p-4 border ${
                    selected.status === "placed"    ? "bg-blush/40 border-blush" :
                    selected.status === "searching" ? "bg-cream/60 border-cream" :
                    "bg-soft/40 border-soft"
                  }`}>
                    <div className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">Placement status</div>
                    {selected.status === "placed" || selected.status === "pending" ? (
                      <>
                        <div className="text-sm font-bold text-slate-800">{selected.company}</div>
                        <div className="text-xs text-slate-500 mt-0.5">{selected.role}</div>
                        <div className="mt-2 text-xs font-semibold text-[#2E7DF7]">
                          {selected.status === "placed" ? "✅ Internship confirmed" : "⏳ Awaiting admin validation"}
                        </div>
                      </>
                    ) : (
                      <div className="text-sm text-slate-500">No internship match yet.</div>
                    )}
                  </div>
                </div>
              );
              })() : (
              <div className="card border border-slate-200 p-10 text-center">
                <div className="text-4xl mb-3">👆</div>
                <p className="text-sm text-slate-400">Select a student to view details.</p>
              </div>
            )}
          </div>

        </div>
      
    </AdminLayout>
  );
}
